import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p41_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor maxpool1d_cuda(torch::Tensor x, int64_t kernel_size, int64_t stride, int64_t padding, int64_t dilation);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool1d_cuda", &maxpool1d_cuda, "MaxPool1d CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

// Block size for the output dimension tile
#define BLOCK_SIZE 256

// Shared memory tiled max-pool1d kernel.
// Grid: blockIdx.x -> output tile, blockIdx.y -> channel, blockIdx.z -> batch
// Each block handles BLOCK_SIZE output positions for one (batch, channel) row.
// Shared memory holds the input elements needed by this tile plus right halo.
template <int KS>
__global__ void maxpool1d_smem_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int L,
    int outL,
    int stride,
    int padding,
    int dilation
) {
    // Which (batch, channel) row
    int c = blockIdx.y;
    int n = blockIdx.z;
    int C = gridDim.y;

    // Base pointer for this (n, c) row
    const float* row_in  = input  + (n * C + c) * L;
    float*       row_out = output + (n * C + c) * outL;

    // First output index handled by this block
    int out_tile_start = blockIdx.x * BLOCK_SIZE;

    // Corresponding first input index (before padding offset)
    // output[i] uses input[i*stride - padding + k*dilation], k=0..KS-1
    // First input needed: out_tile_start * stride - padding
    // Last  input needed: (out_tile_start + BLOCK_SIZE - 1) * stride - padding + (KS-1)*dilation
    int in_start = out_tile_start * stride - padding;
    int halo     = (KS - 1) * dilation;
    int smem_len = BLOCK_SIZE * stride + halo;  // covers all inputs for this tile

    // Shared memory: dynamically sized
    extern __shared__ float smem[];

    // Cooperatively load smem
    for (int i = threadIdx.x; i < smem_len; i += BLOCK_SIZE) {
        int global_idx = in_start + i;
        smem[i] = (global_idx >= 0 && global_idx < L) ? __ldg(row_in + global_idx) : -FLT_MAX;
    }
    __syncthreads();

    // Each thread computes one output position
    int out_idx = out_tile_start + threadIdx.x;
    if (out_idx < outL) {
        // Local offset in smem for this output's window start
        int local_start = threadIdx.x * stride;
        float val = -FLT_MAX;
        #pragma unroll
        for (int k = 0; k < KS; k++) {
            int s = local_start + k * dilation;
            // s is always within [0, smem_len) by construction
            val = fmaxf(val, smem[s]);
        }
        row_out[out_idx] = val;
    }
}

// Generic (runtime KS) fallback kernel
__global__ void maxpool1d_generic_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int L,
    int outL,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int c = blockIdx.y;
    int n = blockIdx.z;
    int C = gridDim.y;

    const float* row_in  = input  + (n * C + c) * L;
    float*       row_out = output + (n * C + c) * outL;

    int out_tile_start = blockIdx.x * BLOCK_SIZE;
    int in_start = out_tile_start * stride - padding;
    int halo     = (kernel_size - 1) * dilation;
    int smem_len = BLOCK_SIZE * stride + halo;

    extern __shared__ float smem[];

    for (int i = threadIdx.x; i < smem_len; i += BLOCK_SIZE) {
        int global_idx = in_start + i;
        smem[i] = (global_idx >= 0 && global_idx < L) ? __ldg(row_in + global_idx) : -FLT_MAX;
    }
    __syncthreads();

    int out_idx = out_tile_start + threadIdx.x;
    if (out_idx < outL) {
        int local_start = threadIdx.x * stride;
        float val = -FLT_MAX;
        for (int k = 0; k < kernel_size; k++) {
            val = fmaxf(val, smem[local_start + k * dilation]);
        }
        row_out[out_idx] = val;
    }
}

torch::Tensor maxpool1d_cuda(
    torch::Tensor x,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t dilation
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3, "x must be 3D");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int N = x.size(0);
    int C = x.size(1);
    int L = x.size(2);

    int64_t outL = (L + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C, outL}, x.options());

    if (outL <= 0) return output;

    int grid_x = (outL + BLOCK_SIZE - 1) / BLOCK_SIZE;
    dim3 grid(grid_x, C, N);
    dim3 block(BLOCK_SIZE);

    // smem_len = BLOCK_SIZE * stride + (kernel_size-1)*dilation
    int smem_len = BLOCK_SIZE * (int)stride + (int)(kernel_size - 1) * (int)dilation;
    int smem_bytes = smem_len * sizeof(float);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    const float* inp = x.data_ptr<float>();
    float*       out = output.data_ptr<float>();

    // Dispatch to compile-time unrolled kernel for common kernel sizes
    if (kernel_size == 8) {
        maxpool1d_smem_kernel<8><<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)stride, (int)padding, (int)dilation);
    } else if (kernel_size == 4) {
        maxpool1d_smem_kernel<4><<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)stride, (int)padding, (int)dilation);
    } else if (kernel_size == 2) {
        maxpool1d_smem_kernel<2><<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)stride, (int)padding, (int)dilation);
    } else if (kernel_size == 3) {
        maxpool1d_smem_kernel<3><<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)stride, (int)padding, (int)dilation);
    } else if (kernel_size == 16) {
        maxpool1d_smem_kernel<16><<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)stride, (int)padding, (int)dilation);
    } else {
        maxpool1d_generic_kernel<<<grid, block, smem_bytes, stream>>>(
            inp, out, L, (int)outL, (int)kernel_size, (int)stride, (int)padding, (int)dilation);
    }

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Max Pooling 1D.
        """
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the Max Pooling 1D layer.

                Args:
                    kernel_size (int): Size of the window to take a max over.
                    stride (int, optional): Stride of the window. Defaults to None (same as kernel_size).
                    padding (int, optional): Implicit zero padding to be added on both sides. Defaults to 0.
                    dilation (int, optional): Spacing between kernel elements. Defaults to 1.
                    return_indices (bool, optional): Whether to return the indices of the maximum values. Defaults to False.
                """
        self.maxpool = nn.MaxPool1d(kernel_size=kernel_size, stride=stride, padding=padding, dilation=dilation, return_indices=return_indices)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Max Pooling 1D to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, num_features, sequence_length).

                Returns:
                    torch.Tensor: Output tensor with Max Pooling 1D applied, shape (batch_size, num_features, output_sequence_length).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        # Attempt fast CUDA path
        try:
            mp = self.maxpool
            if (x.is_cuda and x.dtype == torch.float32 and x.dim() == 3
                    and x.is_contiguous() and not mp.return_indices):
                ks = mp.kernel_size
                st = mp.stride
                pa = mp.padding
                di = mp.dilation
                # Normalize tuple-or-int
                ks = ks[0] if isinstance(ks, tuple) else int(ks)
                st = st[0] if isinstance(st, tuple) else int(st)
                pa = pa[0] if isinstance(pa, tuple) else int(pa)
                di = di[0] if isinstance(di, tuple) else int(di)
                if st is None:
                    st = ks
                return _stark_get_extension().maxpool1d_cuda(x, ks, st, pa, di)
        except Exception:
            pass
        return self.maxpool(x)
        # <<<END_IMPROVE>>>

