__global__ void maxpool1d_generic_direct_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int L,
    int outL,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int c = blockIdx.y;
    int n = blockIdx.z;
    int C = gridDim.y;

    const float* row_in  = input  + ((long long)n * C + c) * L;
